#!/usr/bin/env python3
"""Render the editor handoff from the retained, validated observations."""
import collections,json,pathlib,hashlib
ROOT=pathlib.Path(__file__).resolve().parent

def main():
 result=json.loads((ROOT/'results/summary.json').read_text());claims=json.loads((ROOT/'claims.json').read_text())
 def fmt(value):return f'{value:.3f}'
 def interval(bounds,scale=1):return '['+', '.join(fmt(x*scale) for x in bounds)+']'
 def row(cell,method,filt='all'):
  return next(x for x in result[cell]['queries'] if x['method']==method and x['filter']==filt)
 def obs(cell,kind):return [r for r in result[cell]['observations'] if r['kind']==kind]
 lines=['# Storage benchmark results','',
 'The vector query comparisons use 100,000 seeded synthetic unit vectors of 384 float32 dimensions and 200 independent query vectors per comparison cell. They measure storage behavior, algorithmic recall and client-observed latency, not embedding semantics. The paired query-level 95% intervals below are conditional on this corpus and one index build; they do not measure between-build, hardware or production uncertainty.','',
 'Hardware: 32-thread x86 AMD CPU host, about 28 GiB usable RAM, NVMe-backed ZFS for database data and scratch, CPU only. Each server and client is limited to 2 CPUs and 3 GiB RAM, run sequentially by store on a shared host. Numerical worker pools use one thread.','',
 'Observed stack: Python 3.12.12, NumPy 2.5.5, pgvector 0.8.7 on PostgreSQL 18.7, Redis 8.10.3, Valkey bundle 9.2.0 (Redis compatibility version 7.2.4), Memcached 1.6.45, SQLite 3.46.1 with sqlite-vec 0.1.9, local MongoDB 8.2.11, and DuckDB 2.0.1 with VSS revision 3685131eac for the separate memory probe. Exact runtime strings and dependency versions are retained in the raw files.','',
 '## Published claims against local observations','',
 '| Published claim | Local observation | N / uncertainty / interpretation |','|---|---|---|']
 pg_index={r['method']:r for r in obs('postgres','index')}
 iv=pg_index['ivfflat'];hn=pg_index['hnsw']
 lines.append(f"| pgvector: IVFFlat builds faster and is smaller than HNSW | IVFFlat {iv['build_ms']/1000:.3f} s, {iv['bytes']:,} B; HNSW {hn['build_ms']/1000:.3f} s, {hn['bytes']:,} B | One build each, no interval; supports the trade-off on this fixture |")
 for filt,published in [('tenpct','ef40 and 10% filter: about 4 matches'),('fivepct','ef40 and 20 equal tenants: about 2 matches'),('tiny','ef40 and 5000 equal tenants: usually zero')]:
  a=row('postgres','hnsw_default',filt);b=row('postgres','hnsw_iterative',filt)
  lines.append(f"| pgvector: {published} | Default mean {a['mean_count']:.3f} {interval(a['mean_count_ci95'])}; iterative {b['mean_count']:.3f} {interval(b['mean_count_ci95'])} returned of 10 | 200 paired queries, 95% intervals; endpoint bounds use Wilson; tests this distribution only |")
 storage=obs('postgres','storage')[0]
 lines.append(f"| pgvector: vector(d) is 4d+8 B, so 1,544 B at d=384 | pg_column_size={storage['column_bytes']:,} B; table={storage['table_bytes']:,} B for 100,000 rows | Deterministic size, no sampling CI; 1M/10M extrapolations were not loaded |")
 rm={r['method']:r for r in obs('redis','memory')}
 ratio=rm['VS_NOQUANT']['total_bytes']/rm['VS_Q8']['total_bytes']
 lines.append('| pgvector HNSW index caps: vector 2,000; halfvec 4,000; bit 64,000; sparsevec 1,000 nonzero | Each cap accepted, cap+1 rejected; sqlite-vec separately accepted 8,192 dimensions and rejected 8,193 | Two boundary cases per type; no sampling interval |')
 lines.append(f"| Redis Vector Sets: default int8 vector codes are about 25% of float32 | Total allocated memory delta: Q8 {rm['VS_Q8']['total_bytes']:,} B; NOQUANT {rm['VS_NOQUANT']['total_bytes']:,} B, {ratio:.3f}x reduction | 100,000 vectors, one graph build each; total includes graph and ids, so this is not a test of code bytes alone |")
 mongo_memory={r['method']:r for r in obs('mongo','whole_server_memory')}
 mongo_file={q:mongo_memory[q]['file_proxy']['compound_adjusted_file_proxy_bytes'] for q in ['none','scalar','binary']}
 scalar_file_ratio=mongo_file['none']/mongo_file['scalar'];binary_file_ratio=mongo_file['none']/mongo_file['binary']
 lines.extend([
 '| MongoDB: scalar 3.75x and binary 24x vector-index RAM reduction | Independent vector-file proxies and Java RSS are listed below for fresh local containers | Different metrics; they cannot verify the advertised Atlas RAM factors |',
 '| Raw quantization code widths | float32 153,600,000 B; float16 76,800,000 B; int8 38,400,000 B; packed bits 4,800,000 B | 100,000 x 384; exact payload allocations, 2x/4x/32x; no graph, database or allocator overhead |',
 '| Memcached max key 250 B | 250 accepted; 251 and embedded space rejected; raw TAB and byte 0x01 accepted and read back | Boundary behavior tests, no population CI |',
 '| Memcached 30-day relative-expiry boundary | 30 days and absolute 31-day timestamp retained; relative 31 days immediately absent; 1 second expired; zero retained | Five protocol cases, not a retention reliability estimate |',
 '| Memcached warm restart preserves items; extstore is not durable | Graceful SIGUSR1 retained 100/100; SIGKILL retained 0/100; extstore had real external writes and lost its index on restart | One controlled run per mode; no power-failure guarantee |',
 '| Claude Code 200 lines/25KB and Cursor 500-line guidance | A plain local file retained all 300 lines / 45,900 B; closed harness caps cannot be reproduced locally | Filesystem control only; no claim about Claude or Cursor adherence |',
 '| turbopuffer 874 ms cold / 14 ms cached p50 at 1M documents; <=200 ms commit | Cannot be reproduced locally: proprietary managed backend and unspecified original workload/hardware | No substitute local latency presented as an equivalent |',
 '| Cloudflare Vectorize 1536 dimensions, 10KiB metadata, topK50/100, batches1000/5000; AWS preview40B vectors | Cannot be reproduced locally: hosted quotas and private historical traffic | Not locally measurable |',
 '| Provider prompt-cache thresholds, prices and lifetimes | Cannot be reproduced locally with open weights; quoted cost arithmetic checked separately | No hosted calls or billing verification |','',
 '## Measured local query cells','',
 'All vector cells have N=200 queries and k=10. Recall is the fraction of exact top-10 ids recovered. PostgreSQL exact results agree with all 200 SQLite and Redis/Valkey FLAT results. Median intervals use 2,000 bootstrap resamples with a fixed seed; recall intervals resample whole queries, keeping each query\'s ten neighbors together. All-perfect or all-zero samples use conservative bounded-mean intervals derived from Wilson event-rate bounds instead of zero-width bootstrap intervals. Exact PostgreSQL reference recall is 100% by definition. Full-list return rates have Wilson intervals in summary.json. p95/p99 are descriptive order statistics from 200 queries and are not production-tail guarantees.','',
 '| Store / method / filter | Recall@10, % (95% CI) | Median ms (95% CI) | p95 / p99 ms |',
 '|---|---:|---:|---:|'])
 for cell in ['sqlite','postgres','redis','valkey','mongo']:
  for r in result[cell]['queries']:
   lines.append(f"| {cell} / {r['method']} / {r['filter']} | {r['mean_recall']*100:.2f} {interval(r['mean_recall_ci95'],100)} | {r['median_ms']:.3f} {interval(r['median_ms_ci95'])} | {r['p95_ms']:.3f} / {r['p99_ms']:.3f} |")
 lines.extend(['','## MongoDB memory measurements','',
 'Published RAM reductions are scalar 3.75x and binary 24x. The local file-based working-set proxy gives '+f'{scalar_file_ratio:.3f}x and {binary_file_ratio:.3f}x'+', respectively, at 100,000 x 384 dimensions. This is not a direct measurement of Atlas Required Memory or peak RAM.','',
 '| Quantization | Independent file proxy, B | Java process RSS, KiB | Container memory |', '|---|---:|---:|---|'])
 for q in ['none','scalar','binary']:
  m=mongo_memory[q];java=next((l.split()[-1] for l in m['process_rss_kib'].splitlines() if 'java' in l),'unavailable')
  lines.append(f"| {q} | {mongo_file[q]:,} | {java} | {m['container_stats']['MemUsage']} |")
 lines.extend(['',
 'Each mode has a fresh server and one index build; no statistical interval is justified for these memory snapshots. The file proxy sums .vex and .veq, includes .vec only without quantization, and estimates compound-file contribution from visible file proportions. Temporary files and background merges affect it. Zero named vector-file RSS means the data is in compound/temporary mappings, not that the index uses no RAM; per-extension mapped RSS/PSS is retained in the raw record.','',
 'The retrieved public mongot source contains an estimator fallback with the advertised 3.75x/24x constants. This experiment does not use that fallback, because it would be circular evidence for those ratios. That retrieved source is not asserted to be the bundled localDev build.',''])
 lines.extend(['','## Reproduce','',
 'From the repository root, run `bash benchmarks/stores/reproduce.sh`. It requires Docker with Buildx, a POSIX shell, host Python 3.10 or newer, internet access, and free loopback ports 39750 through 39757. It installs nothing globally. Re-running archives prior cell JSONL files before creating new ones, and replaces the summaries and source-retrieval manifest; the final step regenerates this report from the new summaries.','',
 'The Dockerfile pins the base image digest and requirements.txt pins all resolved Python packages. run.py pins PostgreSQL/pgvector, Redis, Valkey, Memcached and local Atlas images by digest; prefix.py pins llama.cpp and the model revision. Initial image versions are retained by each worker in its JSONL output.','',
 'Data: original synthetic fixture, generated by worker.py with NumPy default_rng seed 20261122. There are 1,000 unit-normalized Gaussian centers; each data/query vector chooses a center independently, adds Gaussian noise with standard deviation 0.08 and is normalized. Integer tenant labels are independent of the center and use row id modulo 10, 20 or 5000. No text dataset, embedding weights or model judge is involved in these vector tests. Code is MIT; the generated synthetic fixture is available under CC0-1.0. Each item is flushed and fsynced immediately; rerunning a cell archives its earlier raw output and rebuilds the index rather than mixing queries from different graph builds. Use run.py --cells to rerun only incomplete stores. No fixture vectors or model weights are retained.','',
 'The separate DuckDB memory probe uses 100,000 uniform-random FLOAT[384] arrays with SQL setseed(0.123), not the normalized query-comparison fixture. Its 32 MiB buffer setting is not a cap on whole-process or HNSW memory.','',
 'The prefix behavior probe uses Qwen2.5-0.5B-Instruct Q4_K_M, Apache-2.0, revision 9217f5db79a29953eb74d5343926648285ec7e67. It is one save/erase/restart/restore demonstration: the cold prompt processed 889 tokens, and the restored fresh process reused 888 tokens while processing one. It is not a generation-quality or speed benchmark, and no confidence interval is inferred.','',
 'Primary-source provenance is in results/sources.json with retrieval time, exact URL and SHA-256. Mutable documentation is identified by its fetched content hash, not silently treated as a release snapshot. Documentation pages are not redistributed. The MongoDB markdown pages are included because their HTML counterparts omit most body text. Software licenses include PostgreSQL/pgvector permissive licenses, Valkey BSD-3, Memcached BSD, sqlite-vec Apache-2.0/MIT, Redis 8 AGPL/RSAL/SSPL options, and MongoDB/mongot SSPL; this is not a relicensing of dependencies.','',
 '## Limits and scope','',
 'Controls: PostgreSQL HNSW m=16, ef_construction=64 and ef_search=40, with iterative scans off or strict_order; IVFFlat 100 lists and probes 1 or 10. ANN queries disable sequential scans and retain EXPLAIN output. Exact filtered baselines deliberately scan the table without an additional tenant index. Redis/Valkey Query Engine and Vector Set cells retain their engine defaults other than the selected index/quantization type; FT.INFO and VINFO are retained. MongoDB numCandidates=100 and limit=10 are explicit; each quantization mode has a fresh server, database and index to isolate retained JVM/index memory. These are different search-effort controls, not equally tuned products. Query Engine readiness requires num_docs=N and initial indexing completion where the engine exposes that field; tiered HNSW buffers/background work may still be present in FT.INFO during the first reads.','',
 'SQLite measures L2 and the other vector cells use cosine on the same unit-normalized inputs. Independent exact result sets are checked for agreement. Backend graph randomization is not exposed or seeded by this harness, so repeated ANN builds can return different neighbors even though the corpus and query seed is fixed.','',
 'These are one-build, serial, warm-client comparisons on shared hardware. There is no throughput saturation test, no multi-host replication/failover, no semantic task scoring, no production query distribution and no power cut. Server CPU/cache contention, build order, dimensions, corpus geometry and filters affect results. No universal corpus-size threshold follows. Binary codes are not rescored by the Redis Vector Set cell; local Atlas uses its own default quantized-search behavior.','',
 'SQLite here loads version 3.46.1 from the pinned Python image, with sqlite-vec 0.1.9. This is different from the book\'s patched SQLite 3.51.3. The single-threaded probes do not test or validate the rare WAL-reset corruption fix; use the patched library in production.','',
 'The inventory covers externally sourced numeric results, limits, prices and relevant measured storage behaviors in the six assigned chapters. Release/version dates, license terms, product lists, architectural descriptions without a measured claim, illustrative sizes and token estimates are not benchmarks. No externally sourced Memcached throughput number or pgvector quantization recall/speed number appears in these reviewed chapter snapshots; the Memcached batch-GET timings are new controls. Existing blocks marked Tested or Test run are the book\'s prior tests and are excluded, including the 10,000 x 1536 Redis timing/memory table, 20,000-vector PostgreSQL walkthrough, Memcached oversized-item fixture and toy store/MaxSim examples. The new local tests may overlap those features as controls.','',
 'Browser SQLite backend constraints and vLLM/LMCache offload behavior remain documentation only. RedisVL defaults were checked in the published wheel, while DuckDB-vss has a separate memory probe; neither is a semantic-quality benchmark. Warm-restart mmap and extstore backing files are on ZFS, not tmpfs or DAX. The extstore load pauses 50 ms after every 100 writes so the probe tests cold-value recovery, not peak ingestion throughput. The MLX engine routes require a Mac, which this task prohibits. REPORT.md lists each disposition explicitly rather than claiming these were measured.','',
 '## Cleanup and unsuccessful attempts','',
 'results/resource-proof*.json retain before/after df, process-name and container listings, owned-container labels, removed scratch status and completed-cell timings. Servers and workers have hard memory limits totaling 6 GiB; the separate prefix server has a 2 GiB cap. Database data, extension caches, generated data and model downloads use /data/scratch/membench/stores/ on ZFS; the runner stops before large writes if the shared system filesystem has under 20 GiB free. The corpus is small enough that data files plus the pinned images stay below the 20 GB task budget. Shared images/services are preserved. Final additional image/cache cleanup is recorded in results/cleanup.json.','',
 'Unsuccessful attempts are retained separately and are not included in the summary: a shared host-root filesystem filling during optional PostgreSQL postprocessing, unescaped SQL percent signs with Psycopg, a port precheck seeing TCP TIME_WAIT, a PostgreSQL parallel-index-build shared-memory limit, and readiness that accepted a Docker TCP proxy before PostgreSQL was serving SQL. The final harness escapes modulo operators, enables SO_REUSEADDR for the port reservation, disables parallel maintenance workers and retries a real SQL connection, and binds database files to a temporary directory on the ZFS scratch filesystem that cleanup removes.',''])
 (ROOT/'README.md').write_text('\n'.join(lines))
 report=['# Editor handoff: externally sourced storage figures','',
 'Each item below identifies the chapter sentence or table row, the published claim, its local disposition, evidence and a replacement of at most two sentences. Full numeric results and setup differences are in README.md and results/summary.json. The source chapter hashes in claims.json identify the exact reviewed build.','',
 'Do not silently turn a documentation limit, hosted price, one-run observation or an arithmetic extrapolation into a locally measured benchmark. Do not attach the local CPU timings to hosted-service claims.','']
 replacements={
  'S11':'This book reproduced a lost update when two writers read the same old file and then replaced it without locking. This proves the failure is possible, not how often it occurs.',
  'S12':'This book created an HNSW index on vector(2000) and observed rejection at vector(2001). These are index limits, not the largest dimensions the column can store.',
  'S13':'This book created an HNSW index on halfvec(4000) and observed rejection at halfvec(4001). The larger indexable dimension limit does not establish recall for a particular embedding model.',
  'S14':'This book created an HNSW index on bit(64000) and observed rejection at bit(64001). This is an index-validator test, not a large-corpus timing result.',
  'S15':'This book indexed a sparse vector with 1,000 nonzero elements and observed rejection when the stored vector had 1,001. The column dimension and nonzero-element limit are different constraints.',
  'S16':f"On this book's 100,000-vector, 384-dimension fixture, IVFFlat built in {iv['build_ms']/1000:.3f} seconds using {iv['bytes']:,} index bytes, versus HNSW's {hn['build_ms']/1000:.3f} seconds and {hn['bytes']:,} bytes. Each index was built once, so these observations have no between-build interval.",
  'S17':f"This book confirmed hnsw.ef_search=40 and tested m=16 with ef_construction=64 on 100,000 vectors. Unfiltered recall@10 was {row('postgres','hnsw_default')['mean_recall']*100:.2f}% over 200 queries; see the companion benchmark for its interval and filtered results.",
  'S18':f"This book confirmed ivfflat.probes defaults to 1 and built 100 lists for 100,000 vectors. Increasing probes from 1 to 10 changed recall@10 from {row('postgres','ivfflat_default')['mean_recall']*100:.2f}% to {row('postgres','ivfflat_probes10')['mean_recall']*100:.2f}% on the same 200 queries, which does not establish a universal tuning rule.",
  'S19':f"This book used exact top-10 results as ground truth for 200 queries over 100,000 vectors and measured a median read of {row('postgres','exact')['median_ms']:.3f} ms. It tested one corpus size, so it did not measure a latency-growth curve.",
  'S20':f"With ef_search=40, this book measured mean result counts of {row('postgres','hnsw_default','fivepct')['mean_count']:.3f} for 20 equal tenants and {row('postgres','hnsw_default','tiny')['mean_count']:.3f} for 5,000 tenants across 200 queries. These are observations for this fixture, not a per-query recall guarantee.",
  'S21':f"This book measured {storage['column_bytes']:,} bytes for one 384-dimension vector and {storage['table_bytes']:,} table bytes for 100,000 rows. Million-row and ten-million-row sizes remain arithmetic extrapolations rather than loaded tests.",
  'S22':f"This book's default HNSW scan returned a mean {row('postgres','hnsw_default','fivepct')['mean_count']:.3f} rows for a 5% filter, compared with {row('postgres','hnsw_iterative','fivepct')['mean_count']:.3f} with iterative scanning. With a 0.02% filter, the iterative scan still averaged only {row('postgres','hnsw_iterative','tiny')['mean_count']:.3f} rows under its work limit.",
  'S23':f"For 100,000 vectors of 384 dimensions, this book measured {rm['VS_Q8']['total_bytes']:,} allocated bytes with default Q8 and {rm['VS_NOQUANT']['total_bytes']:,} without quantization, a {ratio:.3f}x total-memory reduction. Eight-bit code values take one quarter of float32 payload space, but graph and id overhead prevent treating that as a fourfold reduction in the whole set.",
  'S24':'This book tested unquantized identical, orthogonal and opposite vectors and received VSIM scores of 1, 0.5 and 0. These support s=(1+cosine)/2 for this API; distance thresholds use a different scale.',
  'S25':'This book tested an attribute filter over three controlled elements and received only the matching element. It did not measure filtered Vector Set recall at scale.',
  'S27':'This book exhausted a small Redis and Valkey memory budget with 4,000 acknowledged writes per policy. noeviction produced write errors, while allkeys-lru accepted the writes and evicted earlier keys.',
  'S28':'This book tested DELEX IFEQ with a wrong owner and the correct owner: the first removed nothing and the second removed the lease. This is a single-instance behavior test, not a failover safety result.',
  'S30':'This book confirmed the 250-byte limit, but its raw TCP probe stored and read back keys containing a tab or byte 0x01, despite the documented key-format restriction. Hash long prompts and validate keys in the client, rather than relying on every restriction being enforced by the server.',
  'S31':'This book retained values with zero expiry, a 30-day lifetime and an absolute timestamp 31 days ahead, but a relative 31-day value was immediately absent. A one-second value expired, and zero expiry did not prevent eviction in the capacity test.',
  'S32':'This book retained all 100 values after the documented SIGUSR1 warm shutdown and none after SIGKILL. This process-restart test does not establish power-loss durability.',
  'S33':'This book wrote 10,000 values of 8 KiB and confirmed extstore had written objects before restarting the process. Values visible before restart were absent afterward, so external storage did not preserve the cache index.',
  'S34':'Memcached documents warm restart as unsupported with extstore; this book found that both flags were nevertheless accepted at startup. Startup acceptance does not establish correctness for the combined configuration.',
  'S35':'This book filled a 64 MiB Memcached cache with 20,000 values of 8 KiB and observed eviction despite zero time expiry. The companion results retain the server and slab counters.',
  'S47':f"For a condition matching 10% of the rows and ef_search=40, this book measured a mean {row('postgres','hnsw_default','tenpct')['mean_count']:.3f} returned rows across 200 queries. Iterative scanning returned ten in each of those queries, but not for every more-selective filter.",
  'S54':'This book observed result starvation when pgvector applied selective filters after its HNSW scan. This tests one implementation and does not establish every vector store\'s filtering behavior.',
  'S56':'This book held an uncommitted write in one SQLite connection: a second connection could read the committed snapshot, but its write waited about 50 ms and failed with database locked. This checks one local contention schedule, not concurrent throughput.',
  'S57':'This book used an FTS5 trigram index to find an identifier through its substring. One controlled match does not establish retrieval quality over a real corpus.',
  'S58':'This book passed OR syntax, a quoted literal and an unfinished quote through a parameterized FTS5 MATCH query and observed different results or a parse error. SQL parameter binding did not make the MATCH expression literal.',
  'S59':'This book deleted the base row and still found its row id in both the FTS5 and vec0 indexes. An incremental materializer must maintain all three structures together.',
 }
 for c in claims:
  evidence=c['evidence']
  if c['id']=='S23':
   evidence='results/redis-default.json; results/redis.jsonl';c['reason']='A native one-element probe without quantization flags confirmed int8 as the default. Separate 100000 x 384 Q8, NOQUANT and BIN cells measure allocated server memory including graph and ids, not only vector-code bytes.'
  if c['id']=='S29':
   c['disposition']='verified published wheel';evidence='results/defaults.jsonl';c['reason']='AST inspection of the pinned RedisVL 0.32.1 wheel confirms SemanticCache.__init__ has distance_threshold=0.1. The client was not instantiated and cache precision was not tested.'
  if c['id']=='S61':
   c['disposition']='measured local memory probe';evidence='results/duckdb.jsonl';c['reason']='A separate 100000 x 384 uniform-random fixture (SQL seed 0.123) built a HNSW index with DuckDB buffer memory limited to 32 MiB. Whole-process RSS is measured before and after; it does not isolate index allocation or show out-of-core support.'
  if c['topic'].startswith('llama.cpp'):
   c['disposition']='measured local';evidence='results/prefix.json';c['reason']='One CPU-only Qwen2.5-0.5B slot save/erase/restore sequence; cached-token counters verify actual reuse. No production speedup or general retention guarantee is measured.'
  if c['id']=='S51':evidence='results/mongo_none.jsonl; results/mongo_scalar.jsonl; results/mongo_binary.jsonl';c['reason']='Fresh local Atlas containers were tested for all three modes, with file-size proxies and process/mapped-memory snapshots. These quantities differ from the advertised Atlas per-index RAM metric, so they cannot directly validate its factors.'
  disp=c['disposition']
  if disp=='measured local':
   replacement='This book checked this behavior in a pinned local container; the fixture size, local observations and confidence intervals where applicable are reported in the companion storage benchmark. The result applies to that setup and does not establish a universal performance or reliability bound.'
  elif disp=='arithmetic only':
   replacement='Using the stated prices, this book calculates $5.20 for a five-minute write plus one read and $8.20 for a one-hour write plus one read, compared with $8 uncached. These are conditional calculations, not a measured provider bill.'
  elif 'metric differs' in disp:
   replacement=f"Using vector-file snapshots and compound-file proportions, this book estimated {scalar_file_ratio:.3f}x scalar and {binary_file_ratio:.3f}x binary reductions on 100,000 384-dimension vectors. These are file-based proxies, not Atlas Required Memory or peak RAM measurements, so they do not verify MongoDB's 3.75x and 24x RAM claims."
  elif 'documentation only' in disp:
   replacement='The documentation describes this behavior. This book did not run that implementation or establish its behavior on the target platform.'
  else:
   replacement='The source reports this figure or behavior. It cannot be reproduced locally under this book\'s test protocol, so it remains an externally reported claim.'
  replacement=replacements.get(c['id'],replacement)
  if c['id']=='S29':replacement='This book checked the published RedisVL 0.32.1 wheel and confirmed a constructor default distance_threshold of 0.1. That configuration check does not establish a useful production threshold or semantic-cache precision.'
  if c['id']=='S61':
   d=next(r for r in result['duckdb']['observations'] if r['kind']=='resident_index')
   replacement=f"This book built an HNSW index over 100,000 384-dimension vectors with a 32 MiB DuckDB buffer limit and observed process RSS grow from {d['rss_before_bytes']:,} to {d['rss_after_bytes']:,} bytes. This is whole-process memory, not isolated index bytes, and does not establish support for indexes larger than RAM."
  if c['id']=='S45':replacement='This book saved 889 llama.cpp prompt tokens to disk, restarted the server and restored the slot, then observed 888 cached tokens and one newly processed token. This was one CPU-only Qwen2.5-0.5B behavior test, not a speedup benchmark.'
  interpretation='Cannot speak to the published result; it was not reproduced.'
  if disp.startswith('measured local'):interpretation='Supports the behavior in these controlled cases; this is not a universal performance bound.'
  if c['id'] in ['S17','S18','S19','S61']:interpretation='Supports the measured subset of the claim; tuning rules, growth curves or out-of-core limits were not established.'
  if c['id']=='S30':interpretation='Confirms the byte-length boundary, but shows that the server does not enforce all documented character restrictions.'
  if c['id']=='S35':interpretation='Confirms eviction before TTL in a bounded cache; this does not isolate every per-slab eviction scenario.'
  if c['id']=='S34':interpretation='The flags were accepted; this cannot establish correctness or support of the combined configuration.'
  if c['id']=='S29':interpretation='Supports the constructor-default claim, not cache precision or runtime configuration.'
  if c['id']=='S42':interpretation='Supports the conditional arithmetic, not the quoted provider prices or billing behavior.'
  if c['id']=='S51':interpretation='Supports a reduction in the local file proxy, but cannot verify the different advertised RAM metric.'
  c['evidence']=evidence;c['suggested_replacement']=replacement;c['interpretation']=interpretation
  report.extend([f"## {c['id']}: {c['topic']}",'',f"Chapter: `{c['chapter']}:{c['line']}`.",'',f"> {c['book_text']}",'',f"**Disposition:** {disp}. {c['reason']}",'',f"**Evidence:** `{evidence}`.",'',f"**Interpretation:** {interpretation}",'',f"**Suggested replacement:** {replacement}",''])
 report.extend(['## Cleanup evidence and what did not work','',
 'See README.md for corrected harness failures and results/resource-proof*.json for their cleanup records. No failed or partial attempt contributes to the headline statistics. Further corrected harness issues were Redis RESP3 reply shapes, an HNSW readiness timeout, the Docker top PID-column requirement, the unavailable DuckDB 1.4.1 extension and DuckDB 2.0 lambda syntax. MongoDB vector-file memory reads use SYS_PTRACE only inside the owned synthetic-data container; earlier permission refusal is retained as a measurement limitation. Final image/cache/scratch cleanup is documented in results/cleanup.json; a source-only documentation inventory is not a claim that its implementation ran.','',
 'The outstanding empirical gaps are the vendor\'s exact MongoDB per-index RAM metric, power-cut durability, closed/historical/production claims, browser persistence and unrun serving-engine offload implementations. These are named explicitly; none is replaced by a fabricated proxy number.',''])
 (ROOT/'REPORT.md').write_text('\n'.join(report))
